prophet_story_content AS (
  SELECT r.slug,
    string_agg(format('﴿ %s:%s ﴾ %s', q.surah_id, q.ayah_number, coalesce(q.text_uthmani, q.text_ar)), E'\\n\\n' ORDER BY q.surah_id, q.ayah_number) AS quran_text,
    jsonb_agg(jsonb_build_object(
      'url',format('https://quran.com/%s/%s-%s',r.surah_id,r.start_ayah,r.end_ayah),
      'title_ar','القرآن الكريم — مواضع قصة النبي',
      'locator_ar',format('السورة %s، الآيات %s–%s',r.surah_id,r.start_ayah,r.end_ayah),
      'source_type','quran'
    ) ORDER BY r.surah_id,r.start_ayah) AS source_refs
  FROM prophet_story_ranges r
  JOIN public.quran_ayahs q ON q.surah_id=r.surah_id AND q.ayah_number BETWEEN r.start_ayah AND r.end_ayah
  WHERE coalesce(q.text_uthmani,q.text_ar) IS NOT NULL
  GROUP BY r.slug
),
updated_prophets AS (
  UPDATE public.prophets p
  SET metadata=coalesce(p.metadata,'{}'::jsonb)||jsonb_build_object(
    'content_status','quran_primary',
    'story_mode','full_quran_passages',
    'references',c.source_refs,
    'content_depth_version',1
  )
  FROM prophet_story_content c
  WHERE p.slug=c.slug AND p.published=true
  RETURNING p.id
),
updated_sections AS (
  UPDATE public.prophet_sections s
  SET title_ar='النص القرآني الكامل للقصة ومواضعها',
      content_ar='يعرض هذا القسم النص القرآني للمواضع التي سردت قصة النبي أو ذكرت أخباره، مرتبًا بحسب السورة والآية. النص من جدول المصحف المعتمد في ذِكر، ويمكن فتح مواضعه من روابط المراجع أعلى الصفحة. لا تُضاف هنا تفاصيل تاريخية من خارج القرآن على أنها يقين؛ وعند الحاجة إلى تفسير أو خبر تاريخي يجب تمييزه عن النص القرآني وذكر مصدره ودرجة ثبوته.'||E'\\n\\n'||c.quran_text,
      section_type='stories',
      order_num=1
  FROM prophet_story_content c JOIN public.prophets p ON p.slug=c.slug
  WHERE p.id=s.prophet_id AND p.published=true AND s.order_num=1
  RETURNING s.id
)
SELECT (SELECT count(*) FROM updated_prophets) AS prophets_updated,
       (SELECT count(*) FROM updated_sections) AS story_sections_refreshed;

UPDATE public.prophet_sections s
SET title_ar='منهج القراءة والتحقق من الروايات',
    content_ar='تبدأ دراسة قصة النبي بما ثبت في القرآن الكريم، ثم تراجع السنة الصحيحة عند وجود حديث متعلق بالواقعة. أما كتب التفسير والسيرة والتاريخ فتستخدم لشرح السياق وجمع الأخبار، مع التفريق بين الرواية المسندة والخبر المختلف فيه والإسرائيليات. لا تنسب حوارات أو تواريخ أو معجزات إلى نبي لمجرد شهرتها، ولا تعرض القول المختلف فيه بصيغة القطع. اقرأ الآيات في سياق السورة، وارجع إلى تفسير موثوق، ثم قارن الأخبار التاريخية بمصادرها وأسانيدها. روابط الآيات تظهر في مراجع الصفحة، وتضاف إحالات الحديث أو الكتاب عند تحرير مادة تفسيرية مستقلة.'
WHERE s.order_num=2 AND EXISTS (SELECT 1 FROM public.prophets p WHERE p.id=s.prophet_id AND p.published=true);

WITH expanded_companions(slug,bio_ar) AS (VALUES
('khadijah-bint-khuwaylid','أم المؤمنين خديجة بنت خويلد رضي الله عنها زوج رسول الله ﷺ وأول من آمن به وصدّقه عند بدء الوحي. عُرفت برجاحة العقل والصدق والكرم، وكانت صاحبة تجارة ومال سخّرته في وجوه الخير. حين عاد النبي ﷺ من غار حراء خائفًا مما رأى، ثبّتته وذكّرته بما تعرفه من أخلاقه وصلة رحمه وإعانته للمحتاج. وتعرض الرواية الصحيحة في بدء الوحي موقفها وموقف ورقة بن نوفل، ولذلك تُبنى هذه الصفحة على الحديث الصحيح ولا تُضاف إليها تفاصيل شعبية بلا سند. كانت سندًا للنبي ﷺ في سنوات الدعوة الأولى، وواسته في زمن الشدة، وتوفيت قبل الهجرة على المشهور. تُظهر سيرتها اجتماع الإيمان المبكر والحكمة والوفاء وبذل المال، وتذكر القارئ بأن نصرة الحق قد تكون بالعلم والموقف والمال والرعاية. المرجع الرئيس: صحيح البخاري، كتاب بدء الوحي، حديث 3، مع الرجوع إلى كتب السيرة المحققة.'),
('aisha-bint-abi-bakr','أم المؤمنين عائشة بنت أبي بكر الصديق رضي الله عنها زوج النبي ﷺ، ومن أعلم نساء الأمة وأوسع الصحابة رواية وفقهًا. عاشت في بيت النبوة، فتعلمت أحكام العبادة والمعاملة وأحوال الأسرة، ونقلت علمًا احتاج إليه المسلمون بعد وفاة النبي ﷺ. رجع إليها كبار الصحابة والتابعين في مسائل الطهارة والصلاة والأسرة والسيرة، واشتهرت بدقة الفهم وقوة الحفظ. ومن الوقائع الكبرى في حياتها حادثة الإفك، وقد نزلت آيات سورة النور ببراءتها؛ لذلك يجب أن تُروى الحادثة من القرآن والرواية الصحيحة دون إضافة حوار أو تفصيل غير ثابت. تعرض سيرتها دورها في تعليم الحديث والفقه ونقل السنة، مع التنبيه إلى أن بعض المسائل التاريخية وقع فيها نقاش بين الباحثين فلا تعرض الأقوال المختلف فيها بصيغة القطع. المراجع: سورة النور 11–26، وصحيح البخاري حديث الإفك 4141، وكتب التراجم المحققة.'),
('hamzah-ibn-abd-al-muttalib','حمزة بن عبد المطلب رضي الله عنه عم رسول الله ﷺ وأخوه من الرضاعة، ومن السابقين إلى الإسلام. كان ذا مكانة وشجاعة بين قريش، وكان لإسلامه أثر في إظهار قوة المسلمين وحمايتهم في مكة. شهد بدرًا وأُحدًا، واستشهد في أُحد سنة 3هـ. تذكر كتب السيرة مواقفه في نصرة النبي ﷺ، لكن تفاصيل الحوارات والمشاهد تحتاج إلى مراجعة أسانيدها قبل نقلها. تعرض هذه الصفحة الوقائع العامة المعروفة في كتب السيرة، وتفصل بين أصل الحدث وبين التفاصيل التي تختلف رواياتها، ولا تحول الروايات الضعيفة أو القصص المتأخرة إلى حقائق قطعية. ومن الدروس أن الشجاعة تُقاس بنصرة المظلوم والوقوف مع الحق، وأن المكانة الاجتماعية يمكن أن تُسخّر لحماية الضعفاء. المراجع: كتب السيرة المبكرة وتراجم الصحابة، وما صح من أحاديث الفضائل مع بيان درجة الرواية.'),
('zayd-ibn-thabit','زيد بن ثابت الأنصاري رضي الله عنه من كتّاب الوحي، ومن علماء الصحابة في القراءة والفرائض. تعلم القرآن من رسول الله ﷺ، وكان من الشباب الذين أسندت إليهم أعمال علمية دقيقة. بعد وفاة النبي ﷺ شارك في جمع القرآن في عهد أبي بكر الصديق رضي الله عنه، ثم كان ضمن من كُلّفوا بنسخ المصاحف في عهد عثمان رضي الله عنهما لتوحيد المصحف الإمام وتقليل أسباب الاختلاف. تفاصيل الجمع الأول محفوظة في صحيح البخاري، ومنها حديث زيد رقم 4986. لا ينبغي الخلط بين الجمع في عهد أبي بكر ونسخ المصاحف في عهد عثمان؛ فهما مرحلتان مختلفتان. كما عُرف زيد بالعلم بالفرائض، فاجتمع في سيرته حفظ النص وخدمة القضاء والتعليم. تعرض قصته قيمة الأمانة العلمية والتثبت والعمل الجماعي. المرجع: صحيح البخاري، كتاب فضائل القرآن، وأبواب جمع المصحف.'),
('abdullah-ibn-abbas','عبد الله بن عباس رضي الله عنهما ابن عم رسول الله ﷺ، ومن كبار علماء الصحابة في تفسير القرآن والفقه. نشأ قريبًا من بيت النبوة، وأدرك النبي ﷺ صغيرًا، وتلقى عنه الدعاء والعلم، ثم لازم كبار الصحابة وسألهم عن معاني القرآن وأسباب النزول واللغة. وردت أحاديث صحيحة في دعاء النبي ﷺ له بالفقه في الدين وتعليم التأويل. لُقّب بحبر الأمة وترجمان القرآن في كتب العلم، لكن الألقاب لا تغني عن مراجعة أقواله بأسانيدها ومقارنتها بأقوال سائر المفسرين. لم يكن علمه قائمًا على الحفظ وحده؛ بل على السؤال والمذاكرة والتتبع وجمع أقوال الصحابة. وعند عرض تفسير منسوب إليه يجب التحقق من طريقه؛ فليس كل ما يروى في كتب التفسير ثابتًا عنه. المراجع: كتب الحديث المسندة، وتفسير الطبري، وكتب التراجم المحققة.'),
('abu-dharr-al-ghifari','أبو ذر الغفاري رضي الله عنه من السابقين إلى الإسلام، واسمه جندب بن جنادة على المشهور. عُرف بصدق اللهجة والزهد والجرأة في إعلان التوحيد. تروي الأحاديث الصحيحة قصة وصوله إلى مكة وبحثه عن النبي ﷺ وإسلامه ثم إعلانه الشهادة رغم ما لقيه من أذى. نُقلت عنه مواقف في المال والإنفاق والنصيحة، لكن تفاصيل تلك المواقف وألفاظها يجب أن تُنسب إلى مصادرها ولا تجمع في حكاية واحدة دون تمييز. لا يُفهم زهده على أنه دعوة إلى ترك العمل أو تحريم ما أباح الله؛ بل تُقرأ أقواله ضمن سياقها الفقهي والاجتماعي، مع الرجوع إلى شروح الحديث عند اختلاف الفهم. تعرض سيرته نموذجًا للصدق والثبات ومحاسبة النفس، وتفتح بابًا لدراسة تنوع اجتهادات الصحابة في قضايا المال والورع. المرجع الرئيس لقصة إسلامه: صحيح البخاري، حديث 3522.'),
('abu-bakr','أبو بكر عبد الله بن أبي قحافة الصديق رضي الله عنه أول الخلفاء الراشدين وأقرب أصحاب رسول الله ﷺ إليه. كان من السابقين إلى الإسلام، وصاحب النبي ﷺ في الهجرة، وثبت معه في الغار كما ورد في القرآن في سورة التوبة، الآية 40. اشتهر بالصدق والرفق والإنفاق في سبيل الله. بعد وفاة النبي ﷺ بويع بالخلافة، فواجه اضطراب الجزيرة العربية وحروب الردة، وأصر على إنفاذ بعث أسامة، وبدأ في عهده جمع القرآن بعد استشهاد عدد من القراء في اليمامة وأسند العمل إلى زيد بن ثابت. لا تختزل خلافته في الحروب وحدها؛ فقد كان تثبيت الجماعة وحفظ النص القرآني وتنظيم شؤون الدولة من أبرز تحدياتها. استمرت خلافته نحو سنتين وثلاثة أشهر، وتوفي سنة 13هـ. تعرض الصفحة الوقائع مع إحالات إلى الحديث والسيرة، وتفصل بين النص القرآني والروايات التاريخية المختلف في أسانيدها.'),
('umar-ibn-khattab','عمر بن الخطاب رضي الله عنه ثاني الخلفاء الراشدين، أسلم في مكة قبل الهجرة، وكان إسلامه نقطة تحول في قوة المسلمين المعنوية والاجتماعية. لازم النبي ﷺ وشارك في الأحداث الكبرى، ثم تولى الخلافة بعد أبي بكر سنة 13هـ، واستمرت خلافته إلى استشهاده سنة 23هـ. شهد عصره اتساع الدولة الإسلامية في العراق والشام ومصر، ونُظمت الدواوين والعطاء والقضاء والولايات، وتذكر المصادر نشأة التأريخ الهجري في سياق تنظيم المكاتبات والإدارة. اشتهر بالعدل ومحاسبة الولاة والاهتمام بأحوال الرعية، لكن القصص المتداولة عن جولاته الليلية أو أقواله تحتاج إلى تخريج مستقل؛ فلا تنسب إليه عبارة لمجرد شهرتها. تعرض سيرته نموذجًا للمسؤولية العامة والشورى والانضباط ومحاسبة النفس. المراجع: صحيح البخاري في فضائل عمر، وكتب الطبري وابن سعد والبلاذري مع التمييز بين الروايات.'),
('uthman-ibn-affan','عثمان بن عفان رضي الله عنه ثالث الخلفاء الراشدين، ومن السابقين إلى الإسلام، وزوج ابنتي رسول الله ﷺ ولذلك اشتهر بلقب ذي النورين. عُرف بالحياء والإنفاق، وتذكر أحاديث الفضائل مواقفه في تجهيز جيش العسرة وبذل المال في سبيل الله. تولى الخلافة بعد عمر سنة 23هـ، وفي عهده اتسعت الدولة وبرزت الحاجة إلى ضبط المصاحف مع اختلاف الأمصار في وجوه القراءة؛ فنسخ المصحف الإمام وأرسل نسخًا إلى الأمصار، كما يروي صحيح البخاري. شهدت أواخر خلافته اضطرابات سياسية أدت إلى حصاره ثم مقتله سنة 35هـ. هذه المرحلة حساسة تاريخيًا، ولذلك تعرض الخلافات والأحداث بلغة علمية هادئة، مع التفريق بين الروايات المبكرة وما أضيف إليها لاحقًا. المراجع: صحيح البخاري في جمع المصاحف، وكتب التاريخ والتراجم المحققة.'),
('ali-ibn-abi-talib','علي بن أبي طالب رضي الله عنه ابن عم رسول الله ﷺ وزوج فاطمة الزهراء رضي الله عنها، ومن أوائل من أسلم، ورابع الخلفاء الراشدين. نشأ في بيت النبي ﷺ، وشهد معه عددًا من المشاهد، واشتهر بالعلم والقضاء والشجاعة. وردت في فضله أحاديث صحيحة، منها حديث المنزلة وحديث الراية يوم خيبر، وينبغي إيراد كل حديث بلفظه ومصدره دون توسيع دلالته. تولى الخلافة سنة 35هـ في ظرف سياسي شديد التعقيد، ووقعت في عهده أحداث الجمل وصفين والتحكيم والنهروان. هذه الأحداث لا تعرض باعتبارها رواية واحدة مبسطة؛ بل تذكر تعدد المواقف والخلاف في تفاصيل الأخبار، مع توقير الصحابة وترك السب والتجريح. استشهد علي رضي الله عنه سنة 40هـ في الكوفة. المراجع: صحيح البخاري، وكتب الطبقات والتاريخ المبكرة المحققة.'),
('khalid-ibn-walid','خالد بن الوليد المخزومي رضي الله عنه قائد من قادة الصحابة، عرف بالمهارة العسكرية قبل إسلامه، ثم أسلم بعد صلح الحديبية على المشهور. شارك في مؤتة، وتولى القيادة بعد استشهاد القادة الثلاثة، ووصفه النبي ﷺ بأنه سيف من سيوف الله في الحديث الصحيح. قاد جيوش المسلمين في حروب الردة وبلاد الشام والعراق، لكن تفاصيل الحملات وتواريخها تختلف في المصادر التاريخية؛ لذا لا تعرض الأرقام والخطط على أنها قطعية إلا بمرجع محدد. عزله عمر بن الخطاب عن قيادة الجيوش لا يعني إسقاط منزلته، بل يفتح باب دراسة الفرق بين فضيلة الشخص وتنظيم المسؤولية العامة. توفي بحمص سنة 21هـ على المشهور. تعرض سيرته التحول من الخصومة إلى الإسلام وحسن القيادة والعمل ضمن الجماعة. المرجع الحديثي: صحيح البخاري، حديث 3757.'),
('bilal-ibn-rabah','بلال بن رباح الحبشي رضي الله عنه من السابقين إلى الإسلام، عانى الأذى في مكة بسبب ثباته على التوحيد، ثم أعتقه أبو بكر الصديق رضي الله عنه. صار من مؤذني رسول الله ﷺ، وارتبط اسمه بالأذان والصلاة في حياة الجماعة المسلمة. وردت في فضله أحاديث صحيحة، كما نقلت كتب السيرة أخبارًا عن صبره وتعذيبه؛ ويجب التمييز بين أصل المحنة وبين التفاصيل التي تختلف الروايات في ألفاظها. لا تنسب إليه عبارات شعبية أو مشاهد حوارية إلا إذا ثبت مصدرها. وتعرض سيرته انتقاله من الاستضعاف إلى المشاركة في بناء المجتمع، دون أن تجعل مكانته مرتبطة بالصوت وحده؛ فالأساس هو الإيمان والأمانة والثبات. تختلف المصادر في بعض تفاصيل وفاته، لذلك لا نجزم بما اختلف فيه. المرجع: صحيح البخاري في فضائل بلال، وكتب التراجم المحققة.'),
('abu-huraira','أبو هريرة رضي الله عنه صحابي من قبيلة دوس، عُرف بكثرة ملازمته للنبي ﷺ وروايته للحديث. أسلم في السنوات المتأخرة من العهد المدني، ثم لازم النبي ﷺ مدة كان فيها حريصًا على حفظ ما يسمعه وتبليغه. وردت عنه أحاديث في صحيح البخاري وغيره، وتحتاج دراسة سيرته إلى فهم ظروف ملازمته وتفرغه للعلم، وإلى مراجعة الروايات التي تذكر سبب كثرة مروياته. لا يصح اختزال سيرته في عدد الأحاديث؛ بل تعرض معها أمانة الرواية وحرص الصحابة على تبليغ السنة. هذه مادة تحريرية موسعة لمراجعة المصادر، وتظل الصفحة غير منشورة حتى يراجع المحرر كل إحالة ورقم حديث على نسخته المعتمدة. مراجع أولية: صحيح البخاري، كتاب العلم، حديث 118، وكتب تراجم الصحابة.'),
('salman-al-farisi','سلمان الفارسي رضي الله عنه صحابي من بلاد فارس، وتذكر الروايات قصة بحثه الطويل عن الدين الحق حتى وصل إلى المدينة ولقي النبي ﷺ. أصل فضله ثابت في أحاديث مشهورة، كما ارتبط اسمه بمشورة الخندق في كتب السيرة. لكن تفاصيل رحلة البحث ومراحلها ترد بألفاظ وأسانيد متفاوتة، فلا تدمج في نص واحد وكأن كل جزئية فيه صحيحة. يجب أن يُفصل بين الحديث المسند والخبر التاريخي، وأن تذكر درجة الرواية عند نقلها. تعرض هذه المسودة مكانة سلمان واجتهاده في طلب الحق ومشاركته في المجتمع، وتحتاج مراجعة بشرية للمراجع قبل النشر. المرجع المبدئي: صحيح البخاري، حديث 3946، مع دراسة روايات السيرة في كتبها المحققة.'),
('muadh-ibn-jabal','معاذ بن جبل رضي الله عنه من الأنصار ومن أهل العلم والفقه، واشتهر بتعليم الناس والقيام بمهمات علمية ودعوية في حياة النبي ﷺ. وردت أخبار في بعثه إلى اليمن وتعليمه الناس، وينبغي عند عرضها تحديد الحديث ومقارنة طرقه وشروحه قبل اعتماد تفاصيلها. تقدم سيرته قيمة الجمع بين المعرفة والعمل، وأن العلم الشرعي يحتاج إلى فهم النص وحسن تعليم المخاطب ومراعاة حاله. لا تُنسب إليه أحكام أو حوارات مختصرة لمجرد تداولها على الإنترنت. هذه المادة مسودة موسعة لا تزال بحاجة إلى اعتماد المحرر على كل موضع حديثي، ولذلك تبقى غير منشورة إلى حين اكتمال المراجعة. مراجع أولية: جامع الترمذي، حديث 1327، وصحيح البخاري، حديث 3809، مع التحقق من الألفاظ والتخريج.'),
('asma-bint-abi-bakr','أسماء بنت أبي بكر رضي الله عنها صحابية من السابقين، وابنة أبي بكر الصديق وأخت عائشة رضي الله عنهما. تذكر الروايات الصحيحة دورها في أحداث الهجرة وخدمتها لأهل بيت النبي ﷺ، ومن أشهر ما ورد في شأنها خبر ذات النطاقين. تعرض سيرتها معنى الثبات وحسن التدبير وخدمة الحق في الظروف الصعبة، دون إضافة تفاصيل شعبية غير موثقة أو حوارات لم ترد في مصادرها. كما تُظهر أن أدوار النساء في صدر الإسلام لم تقتصر على نقل الأخبار، بل شملت العمل والرعاية وتحمل المسؤولية. هذه مسودة موسعة تحتاج مراجعة أرقام الأحاديث ومطابقة النص مع المصادر قبل النشر، ولذلك تظل حالة النشر كما هي. مراجع أولية: صحيح البخاري، حديث 3905، وصحيح مسلم، حديث 2143.')
)
UPDATE public.companions c
SET bio_ar=e.bio_ar,
    metadata=coalesce(c.metadata,'{}'::jsonb)||jsonb_build_object('content_depth_version',1,'editorial_scope','source_linked_biography')
FROM expanded_companions e
WHERE c.slug=e.slug;

WITH expanded_companion_stories(slug,order_num,content_ar) AS (VALUES
('khadijah-bint-khuwaylid', 1, 'تُقرأ هذه الواقعة من حديث بدء الوحي كاملًا؛ فالحديث يذكر عودة النبي ﷺ من الغار، وطلبه التغطية، ثم ذهاب خديجة به إلى ورقة بن نوفل. ولا تضاف إلى المشهد تفاصيل تصويرية أو حوار غير وارد في الرواية. المعنى التربوي هنا أن التثبيت يبدأ بمعرفة الخلق والسيرة، وأن الإنسان حين يواجه أمرًا جديدًا يحتاج إلى شخص أمين يسمع له ثم يساعده على الرجوع إلى أهل المعرفة. المرجع: صحيح البخاري، حديث 3.'),
('khadijah-bint-khuwaylid', 2, 'تذكر كتب السيرة مكانة خديجة ومالها ومساندتها للدعوة، لكن أرقام الأموال وتفاصيل كل نفقة تحتاج إلى مصدر مستقل. لذلك تعرض المادة معنى البذل والوفاء دون نسبة مبلغ أو حوار إليها بلا سند. ويظهر من حياتها أن الدعم قد يكون مالًا أو حماية أو مشورة أو احتواءً، وأن العمل الصالح لا ينفصل عن حفظ الحقوق. على القارئ التفريق بين الحديث الصحيح وخبر السيرة والتأمل التحريري.'),
('aisha-bint-abi-bakr', 1, 'كانت مرجعية عائشة العلمية نابعة من قربها من بيت النبوة، ومن دقتها في حفظ ما سمعته وشاهدته، ثم تعليم من جاء بعدها. لا يعني ذلك أن كل قول ينسب إليها صحيح؛ بل تُراجع الأسانيد والنصوص قبل الاحتجاج. تُعرض هذه المادة بوصفها مدخلًا إلى علمها في الحديث والفقه، لا بديلًا عن دراسة الروايات نفسها. من المفيد للقارئ مراجعة أبواب العلم والحيض والصلاة في دواوين السنة مع شروحها.'),
('aisha-bint-abi-bakr', 2, 'ينبغي قراءة آيات الإفك في سورة النور 11–26 كاملة، لا اقتطاع آية منها عن سياقها. ويُرجع إلى صحيح البخاري 4141 لسرد الواقعة من رواية عائشة. لا تستخدم هذه القصة لإعادة نشر شائعات أو تعليقات جارحة؛ بل لإظهار خطورة نقل الكلام في الأعراض، ووجوب التثبت قبل تداول أي خبر يمس سمعة إنسان.'),
('hamzah-ibn-abd-al-muttalib', 1, 'أصل إسلام حمزة ونصرته للنبي ﷺ معروف في كتب السيرة، غير أن صياغات الحوار وتفاصيل اللحظة تختلف في الروايات. لذلك يذكر النص الحدث إجمالًا ويضع تنبيهًا للمحرر بضرورة مراجعة الرواية المختارة. الدرس ليس تمجيد القوة لذاتها، بل استخدام المكانة لحماية من يتعرض للظلم. ويُفضل الرجوع إلى ابن هشام والطبقات مع دراسة الأسانيد عند ذكر لفظ محدد.'),
('hamzah-ibn-abd-al-muttalib', 2, 'تُربط واقعة استشهاده بأحداث أُحد كما جاءت في القرآن والسيرة، مع قراءة آل عمران في سياق المعركة. آية آل عمران 169 تقرر منزلة الشهداء، لكنها ليست وصفًا تفصيليًا لمقتل حمزة. ينبغي ألا تضيف المادة مشاهد أو أقوالًا غير موثقة، وأن تركز على الوفاء والتضحية وحفظ حرمة الموتى.'),
('zayd-ibn-thabit', 1, 'حديث زيد في جمع القرآن يشرح مراحل العمل ويذكر استكتاب الشواهد المكتوبة وما كان محفوظًا عند القراء. فلا يقال إن القرآن لم يكن مكتوبًا أو محفوظًا قبل ذلك؛ بل جرى جمع ما كان متفرقًا في صحف جامعة. تعكس الواقعة الدقة والتثبت والتعاون، وتفتح بابًا لفهم تاريخ المصحف من مصدر حديثي أصلي. المرجع: صحيح البخاري 4986.'),
('zayd-ibn-thabit', 2, 'نسخ المصاحف في عهد عثمان مرحلة تالية للجمع الأول، وهدفها تقليل أسباب النزاع في القراءة بين الأمصار. تشرح رواية البخاري دور الصحابة واللجنة والنسخ، ولا يجوز اختزالها في عبارة أن القرآن جُمع لأول مرة في عهد عثمان. يراجع القارئ الحديث كاملًا وشروح العلماء لفهم الفرق بين المراحل. المرجع: صحيح البخاري، كتاب فضائل القرآن.'),
('abdullah-ibn-abbas', 1, 'الدعاء بالفقه لابن عباس ثابت في أحاديث، لكن العلم الذي اشتهر به جاء أيضًا من ملازمة الصحابة والسؤال والتعلم. من الخطأ أن نفهم الدعاء على أنه إعفاء من بذل الجهد. تعرض المادة هذا المعنى مع الفصل بين نص الحديث والشرح التربوي. راجع صحيح البخاري في كتاب العلم وشروح الحديث عند نقل اللفظ.'),
('abdullah-ibn-abbas', 2, 'تنقل كتب التفسير أخبارًا عديدة عن ابن عباس، وبعض طرقها أقوى من بعض. لذلك يجب إرفاق اسم المصدر ورقم الأثر والإسناد أو حكم المحقق حيث يتوفر. لا يكفي أن يقال «قال ابن عباس» دون تحديد الطريق. هذا المنهج يحفظ مقام العالم ويعلم القارئ كيف يميز التفسير المأثور من الأقوال التي لا تثبت.'),
('abu-dharr-al-ghifari', 1, 'تعرض الرواية الصحيحة رحلة أبي ذر للبحث عن النبي ﷺ وإسلامه وإعلانه الشهادة. عند إعادة سردها يجب الالتزام بنص المصدر وعدم إضافة أسماء أو حوارات لم ترد فيه. المعنى هو صدق طلب الحق والتحقق من الخبر من مصدره، مع تقدير ظروف مكة وما كان يواجهه المستضعفون. المرجع: صحيح البخاري 3522.'),
('abu-dharr-al-ghifari', 2, 'مواقف أبي ذر في المال والزهد باب فقهي وتاريخي يحتاج جمع الروايات وشرحها. فلا تختزل آراءه في شعار واحد، ولا يُنسب إليه قول عن حكم المال دون تخريج. ينبغي التفريق بين الحديث المرفوع، والأثر الموقوف، وشرح العلماء، والاستنباط التربوي. وتظل المادة تعليمية لا فتوى في معاملات الناس.'),
('abu-bakr', 101, 'الآية 40 من سورة التوبة هي أصل قرآني في خبر الغار، وتذكر صحبة النبي ﷺ لأبي بكر والسكينة والتأييد. يمكن إضافة تفاصيل الهجرة الأخرى من روايات صحيحة محددة، لكن لا تُختلق حوارات أو مشاهد. الدرس أن التوكل يجتمع مع الإعداد والأخذ بالأسباب، وأن الصحبة وقت الشدة مسؤولية وموقف.'),
('abu-bakr', 102, 'تُذكر أخبار إنفاق أبي بكر وعتقه للمستضعفين في كتب الفضائل والسيرة، لكن ينبغي تحديد الرواية قبل ذكر أسماء أو أعداد أو مبالغ. المعنى التربوي هو جعل المال في نصرة المظلوم وخدمة المجتمع مع مراعاة الحقوق الواجبة. عند الاقتباس يراجع المحرر كتب الحديث والطبقات ولا ينقل العبارات الشائعة بلا تخريج.'),
('umar-ibn-khattab', 103, 'يمكن توثيق إدارة عمر من خلال دراسة نظام الدواوين والولايات والقضاء والعطاء، بدل الاعتماد على قصص مجهولة المصدر. وتُذكر أخبار مراقبته للولاة في سياق كتب التاريخ مع تمييز درجة كل رواية. العدل ليس قصة فردية فقط، بل نظام يمنع التعدي ويتيح محاسبة أصحاب السلطة.'),
('umar-ibn-khattab', 104, 'روايات إسلام عمر وردت بألفاظ مختلفة في كتب السيرة، لذلك تحفظ المادة أصل الحدث وتترك الحوار المفصل لما يثبته المصدر. لا ينبغي استعمال القصة لتبرير العنف؛ بل لفهم تحول الإنسان ومراجعته لمواقفه. يشار إلى مصدر كل رواية قبل اعتمادها في نص نهائي.'),
('uthman-ibn-affan', 105, 'أخبار إنفاق عثمان في تجهيز الجيوش وسائر وجوه الخير تُراجع في أبواب الفضائل بأرقامها، ولا تُعرض الأرقام المالية إلا بعد المطابقة. الدرس أن السخاء مسؤولية، وأن الحياء لا يعفي من القيام بالواجب. تُفصل الرواية عن التعليق التحريري حتى لا يلتبس على القارئ المنقول بالاستنتاج.'),
('uthman-ibn-affan', 106, 'حديث نسخ المصاحف في عهد عثمان يوضح دور اللجنة ومراجعة الصحف وإرسال النسخ. اقرأه كاملًا، وميّز بين الجمع في عهد أبي بكر والنسخ في عهد عثمان. ولا تضف تفاصيل تقنية أو أسماء لم يثبتها المصدر. المرجع الرئيس: صحيح البخاري، كتاب فضائل القرآن.'),
('ali-ibn-abi-talib', 107, 'تُقرأ أحاديث فضائل علي بألفاظها وسياقها، ثم تُعرض أحداث خلافته من مصادر التاريخ المبكرة مع ذكر الاختلاف في الروايات. لا تدمج مواقف الجمل وصفين والنهروان في سردية واحدة متحيزة. القارئ يحتاج إلى معرفة السياق السياسي واحترام الصحابة وترك الألفاظ التي تثير الخصومة.'),
('khalid-ibn-walid', 108, 'حديث وصف خالد بسيف من سيوف الله أصل ثابت لفضيلته، لكن خطط المعارك والأعداد والتفاصيل العسكرية تحتاج مصادر تاريخية محددة. تعرض المادة القيادة بوصفها مسؤولية وتعاونًا لا مجدًا شخصيًا، وتذكر أن قرارات العزل والتعيين تدخل في تنظيم الدولة ولا تلغي فضل القائد. المرجع: صحيح البخاري 3757.'),
('bilal-ibn-rabah', 109, 'تراجع أحاديث فضائل بلال في مصادرها الأصلية، وتُفصل عن روايات السيرة التي تصف ما لقيه في مكة. لا تنسب إليه عبارته المشهورة في كل موقف إلا إذا ثبتت الرواية. وتعرض المادة أثره في الأذان وخدمة الجماعة، ومعنى الكرامة الإنسانية التي لا تقاس باللون أو النسب.')
)
UPDATE public.companion_stories cs
SET content_ar=cs.content_ar||E'\\n\\n'||e.content_ar
FROM expanded_companion_stories e
JOIN public.companions c ON c.slug=e.slug
WHERE cs.companion_id=c.id AND cs.order_num=e.order_num;

WITH expanded_scholars(slug,bio_ar) AS (VALUES
('abu-hanifa','أبو حنيفة النعمان بن ثابت فقيه من الكوفة، ارتبط اسمه بتشكل المدرسة الحنفية التي أصبحت من أوسع المدارس الفقهية انتشارًا. عاش في القرن الثاني الهجري، وتتحدث المصادر عن عنايته بالفقه والنظر في النوازل وتكوين الطلاب، ومن أبرز من نقل مذهبه أبو يوسف ومحمد بن الحسن الشيباني. لا يصح أن تنسب إليه كل مسألة متأخرة في كتب المذهب بوصفها رأيه الشخصي؛ فالمذهب تطور عبر أجيال من أصحابه ومحرريه. كما أن تفاصيل حياته ومواقفه مع الولاة تختلف رواياتها، ولذلك تعرض الصفحة ما تدعمه الدراسات التاريخية وتترك مواضع الخلاف موضحة. دراسة أبي حنيفة تعطي مدخلًا لفهم نشأة الفقه المدرسي وطريقة أهل العراق في الاستدلال وعلاقة الفقيه بالواقع الاجتماعي والقضائي. المرجع الأكاديمي: Encyclopaedia Iranica، مادة Abu Hanifa، إلى جانب كتب طبقات الفقهاء.'),
('ahmad-ibn-hanbal','أحمد بن حنبل إمام من أئمة الحديث والفقه، ولد في بغداد سنة 164هـ وتوفي سنة 241هـ. رحل في طلب الحديث وسمع من علماء الحجاز والعراق واليمن، واشتهر بجمع المسند المرتب على أسماء الصحابة. كان علمه قائمًا على العناية بالأثر والتحري في النقل، مع اجتهاد فقهي نقلته كتب أصحابه. عاصر محنة القول بخلق القرآن في العصر العباسي وثبت على موقفه، وأصبح ذلك جزءًا مهمًا من تاريخ العلاقة بين العلماء والسلطة. يجب عرض هذه المرحلة من خلال المصادر التاريخية وعدم إضافة حوارات من الذاكرة الشعبية. كما ينبغي التفريق بين روايات المسند وبين أحكام الإمام على الحديث؛ فليس كل حديث في المسند صحيحًا بالضرورة. المرجع الأكاديمي: Encyclopaedia Britannica، مادة Ahmad ibn Hanbal، ومصادر التراجم.'),
('malik-ibn-anas','مالك بن أنس إمام دار الهجرة وأحد أئمة الفقه، ولد في المدينة سنة 93هـ على المشهور وتوفي سنة 179هـ. نشأ في بيئة علمية وتلقى الحديث والفقه عن علماء المدينة، واشتهر بكتاب الموطأ الذي يجمع أحاديث وآثارًا وفقهًا عمليًا. تمثل طريقته عناية بعمل أهل المدينة وبالنصوص والآثار، لكن فهم منهجه لا يكون من جملة واحدة بل من قراءة الموطأ وشروح أصول مذهبه. روى عنه عدد كبير من الطلاب وانتشر المذهب المالكي في أقاليم متعددة. تذكر كتب التراجم مواقف له في التعليم والفتوى، وبعض القصص المتعلقة بمحنته تحتاج إلى إسناد قبل عرضها كوقائع قطعية. لا ينبغي وصف الموطأ بأنه كتاب حديث مجرد؛ فهو مصنف يجمع الحديث والفقه والآثار وفق ترتيب فقهي. المرجع: Britannica، مادة Malik ibn Anas، وفهرس الموطأ وشروحه.'),
('shafii','محمد بن إدريس الشافعي إمام من أئمة الفقه، ولد في غزة سنة 150هـ ونشأ بمكة، ثم رحل في طلب العلم إلى المدينة والعراق ومصر. تتلمذ على مالك بن أنس، واتصل بفقهاء العراق، وأسهم في صياغة علم أصول الفقه من خلال الرسالة، وله كتاب الأم في الفقه. اشتهر بجمع الدليل والنظر في دلالات اللغة وطرق الاستنباط، وتطور مذهبه بين مرحلتي العراق ومصر؛ ولذلك يميز العلماء بين القديم والجديد في بعض أقواله. لا تنسب إليه أبيات أو حكم مشهورة دون مصدر، ولا يختزل منهجه في شعار واحد. دراسة الشافعي تقدم صورة عن انتقال الفقه بين الأمصار وتطور أدوات الاستدلال. المرجع: Encyclopaedia Britannica، مادة Abu Abd Allah ash-Shafii، مع الرجوع إلى الرسالة والأم.'),
('bukhari','محمد بن إسماعيل البخاري إمام حافظ من بخارى، ولد سنة 194هـ وتوفي سنة 256هـ. بدأ طلب الحديث مبكرًا، ورحل إلى عدد كبير من الأمصار، وجمع الروايات وقارن الأسانيد والمتون، واشتهر بكتابه الجامع الصحيح المعروف بصحيح البخاري. بوب الكتاب بأبواب فقهية تعكس اختياراته واستنباطاته، ولذلك لا تقتصر دراسته على قراءة المتون بل تشمل تراجم الأبواب وشروح العلماء. وله مؤلفات أخرى في التاريخ والرجال والآداب. صحة أحاديث الصحيح وفق منهج البخاري لا تعني أن كل تفسير أو شرح لاحق جزء من كلامه؛ فالمتن والباب والشرح مستويات مختلفة. تعرض الصفحة رحلته العلمية ومنهجه العام وأثره في خدمة السنة، مع إحالات إلى النصوص والشروح المعتمدة. المرجع: Britannica، مادة al-Bukhari، وصحيح البخاري وشروحه.'),
('al-nawawi','يحيى بن شرف النووي فقيه ومحدث شافعي، ولد في نوى سنة 631هـ وانتقل إلى دمشق لطلب العلم، وتوفي سنة 676هـ. عُرف بالعبادة والانضباط العلمي والتصنيف، وترك مؤلفات صار لها أثر واسع في التعليم، منها رياض الصالحين، والأربعون النووية، وشرح صحيح مسلم، والمجموع في الفقه الشافعي. جمع في كتبه الأحاديث ورتبها وشرح معانيها، مع عناية بالفقه واللغة وآداب طالب العلم. ينبغي التفريق بين نص الحديث الذي يورده وبين شرح النووي أو ترجيحه؛ فالشرح اجتهاد عالم وليس جزءًا من الحديث. نسبة قول إليه تحتاج الرجوع إلى كتابه وموضعه، لا إلى مقتطفات الإنترنت. المرجع الأكاديمي: دراسة King''s College London عن حياة النووي والحديث، إلى جانب كتبه المحققة.'),
('ibn-kathir','إسماعيل بن عمر بن كثير مفسر ومحدث ومؤرخ من علماء الشام في القرن الثامن الهجري، ارتبط اسمه بدمشق وبمدرسة الحديث والتفسير فيها. من أشهر آثاره تفسير القرآن العظيم، والبداية والنهاية، وكتب في الحديث والفضائل. في تفسيره يعتني بجمع الآيات المتعلقة بالموضوع، ثم يورد الأحاديث والآثار وأقوال السلف، مع تفاوت الروايات التي ينقلها؛ ولهذا لا يجوز التعامل مع كل خبر يذكره على أنه صحيح لمجرد وجوده في التفسير. يجب مراجعة تخريج الأحاديث وأحكام المحدثين على الأسانيد، والتمييز بين النص القرآني والتفسير والأخبار التاريخية. أثر ابن كثير واضح في الدراسات القرآنية والتاريخية، لكن قراءة أعماله تحتاج إلى طبعات محققة وفهم سياق عصره. المرجع: دراسة أكاديمية في White Rose/University of Leeds عن ابن كثير والتفسير، وكتب التراجم.'),
('ibn-taymiyya','أحمد بن عبد الحليم بن تيمية عالم حنبلي ولد سنة 661هـ وتوفي سنة 728هـ، وانتقلت أسرته إلى دمشق في طفولته بعد اضطرابات التتار. برز في الحديث والفقه والتفسير والعقيدة والمناظرة، وترك مؤلفات ورسائل كثيرة جمعت لاحقًا في مجموع الفتاوى وغيره. من الكتب المشهورة المنسوبة إليه العقيدة الواسطية ودرء تعارض العقل والنقل ومنهاج السنة. عاش في زمن اضطراب سياسي وفكري، ودخل السجن أكثر من مرة، وتوفي في دمشق. ينبغي دراسة أقواله ضمن سياقها ومقارنة النقول بنصوص كتبه المحققة، وعدم أخذ عبارة مبتورة من الشبكات الاجتماعية بوصفها خلاصة مذهبه. اختلف العلماء والباحثون في عدد من آرائه؛ ومن الإنصاف عرض المسألة مع نسبتها إلى مصدرها وبيان وجود النقاش العلمي حولها. المراجع: Stanford Encyclopedia of Philosophy، وOxford Bibliographies، وكتب التراجم.')
)
UPDATE public.scholars s
SET bio_ar=e.bio_ar,
    metadata=coalesce(s.metadata,'{}'::jsonb)||jsonb_build_object('content_depth_version',1,'editorial_scope','academic_and_primary_source_linked')
FROM expanded_scholars e
WHERE s.slug=e.slug AND s.published=true;

WITH expanded_fictional_stories(slug,extra_content) AS (VALUES
('zikr-story-01','بعد ذلك صار يراجع خطته كل أسبوع بدل أن يضاعفها كل يوم. إذا فاتته جلسة لم يحاول تعويض كل ما فاته دفعة واحدة؛ بل عاد إلى الخطوة التالية. لاحظ أن وجود مصحف في مكان هادئ، وموعد معلوم، وإبعاد الهاتف، جعلت العادة أسهل من انتظار الحماس. شارك فكرته مع صديق يمر بالتجربة نفسها، واتفقا على التشجيع دون مقارنة أو لوم. القصة متخيلة وهدفها التدرج، وليست نقلًا عن واقعة تاريخية.'),
('zikr-story-02','بعد التجربة كتب سليم إجراءً بسيطًا لكل العاملين: فحص السلعة، تصويرها كما هي، كتابة العيب المؤثر، ثم عرضها بسعر يناسب حالتها. وأوضح أن إخفاء العيب قد يحقق ربحًا سريعًا لكنه يهدم الثقة ويعرض المتجر للنزاع. لم يمنع الإجراء كل مشكلة، لكنه جعل الاعتذار والتعويض أسهل عندما يظهر خلل لم يكن معروفًا. القصة متخيلة لتعليم الأمانة في المعاملات، وليست فتوى أو حكاية تاريخية.'),
('zikr-story-03','بعد مدة أرسل أحد أعضاء المجموعة خبرًا جديدًا غير صحيح. هذه المرة لم يسخر منه أحد؛ بل طلبوا المصدر وساعدوه في التحقق ثم نشروا تصحيحًا واضحًا. فهمت مريم أن التثبت لا يعني إحراج المخطئ، بل حماية الناس من أثر المعلومة. كما وضعوا قاعدة ألا ينسبوا حديثًا للنبي ﷺ قبل معرفة مصدره ودرجته. القصة متخيلة ولا تنسب موقفًا تاريخيًا.'),
('zikr-story-04','صار عمر يسأل والدته عن الوقت الذي يناسبها بدل أن يفرض الزيارة وفق جدول عمله وحده. وعندما لم يستطع تلبية طلب، شرح السبب وعرض بديلًا يستطيع الوفاء به. اكتشف أن البر ليس وعدًا كبيرًا يتكرر ثم لا ينفذ، بل اهتمام مستمر وصادق. القصة متخيلة، والمصدر القرآني لمعنى الإحسان هو الإسراء 23–24 والنساء 36.'),
('zikr-story-05','أضاف الفريق خطوة أخرى: لا يُنشر حديث أو حكم إلا مع رابط إلى مصدره الأصلي وبيان ما إذا كان النقل نصًا أو تلخيصًا. وعندما لا تتوفر إحالة دقيقة يكتب المحرر أن المعلومة تحتاج مراجعة بدل أن يملأ الفراغ بتخمين. ساعد ذلك على تقليل الأخطاء وعلى تعليم القارئ كيف يتحقق بنفسه. القصة متخيلة عن العمل التحريري وليست خبرًا تاريخيًا.'),
('zikr-story-06','اتفق الجيران على احترام خصوصية كل أسرة؛ فلا تُلتقط صور للمساعدة ولا تُنشر تفاصيل حاجة أحد دون إذنه. كما لم يجعلوا المساعدة دينًا يجب رده، بل تعاملوا معها بوصفها تعاونًا متبادلًا بحسب القدرة. بذلك أصبحت العمارة أكثر هدوءًا وتعاونًا. القصة متخيلة وهدفها توضيح معنى الإحسان وحسن الجوار.'),
('zikr-story-07','جرب فادي أسبوعًا من دون إشعارات غير ضرورية، ثم راجع أثر ذلك على نومه ومذاكرته. لم يمنع نفسه من استخدام الهاتف تمامًا؛ بل جعل له وقتًا واضحًا. وعندما عاد إلى عادة التصفح الطويل، لم يعتبر الأسبوع فشلًا، بل عدل البيئة وأعاد التجربة. القصة متخيلة عن الانضباط الرقمي وليست نصيحة طبية.'),
('zikr-story-08','قرر المعلم أن يذكر مصدر كل إجابة، وأن يؤجل ما لا يعرفه حتى يراجعه. اكتشف الأطفال أن المعلم الموثوق لا يحتاج إلى ادعاء معرفة كل شيء. صار صندوق الأسئلة مساحة آمنة للتعلم، وصار آدم يكتب السؤال الذي يخجل من طرحه بصوت مرتفع. القصة متخيلة لتشجيع طلب العلم والتواضع.'),
('zikr-story-09','بعد شهر لم تختفِ كل مظاهر الهدر، لكن الأسرة صارت تلاحظها مبكرًا. وضعوا قائمة أسبوعية بما يمكن إصلاحه أو إعادة استخدامه، وناقشوا ما لا يمكن تغييره دون لوم. تعلم الأطفال أن المسؤولية لا تحتاج إلى إعلان كبير؛ بل إلى عادة قابلة للاستمرار واحترام الموارد. القصة متخيلة وليست واقعة دينية تاريخية.')
)
UPDATE public.stories s
SET content=s.content||E'\\n\\n'||e.extra_content,
    metadata=coalesce(s.metadata,'{}'::jsonb)||jsonb_build_object(
      'content_depth_version',1,'fictional',true,'fictional_story',true,
      'not_historical_claim',true,'source_type','fictional_editorial','editorial_status','published'
    )
FROM expanded_fictional_stories e
WHERE s.slug=e.slug AND s.published=true AND s.is_approved=true;

WITH expanded_articles(slug,body_ar,refs) AS (VALUES
('zikr-article-expansion-17', '# أخلاق التجارة

الأمانة في التجارة أساس الثقة بين البائع والمشتري. تبدأ بوصف السلعة كما هي، وبيان العيب المؤثر، والابتعاد عن الغش والتدليس، وعدم استغلال جهل الطرف الآخر. لا يجوز أن يتحول الإعلان إلى وعد لا يستطيع المنتج الوفاء به، ولا أن يُخفى شرط يغير قرار الشراء.

## الصدق في الوصف والميزان

جاء القرآن بالوعيد على التطفيف في سورة المطففين، ودعا إلى الوفاء بالكيل والميزان في مواضع متعددة. ويشمل التطبيق المعاصر دقة الوزن والمقاس، وصحة الصور، ووضوح السعر والرسوم، وبيان سياسة الاستبدال والإرجاع قبل إتمام البيع. كما يدخل فيه عدم استخدام تقييمات مزيفة أو ادعاءات غير مثبتة حول جودة المنتج.

## حق المشتري وحق البائع

العلاقة العادلة لا تعني أن يتنازل أحد الطرفين عن حقه؛ بل أن يعرف كل طرف ما له وما عليه. من حق البائع تحصيل الثمن المتفق عليه، ومن حق المشتري معرفة حقيقة ما يدفع مقابله. وعند النزاع تُراجع الفاتورة والوصف والاتفاق، ويُطلب حل منصف بعيدًا عن التشهير أو التهديد.

## تطبيق عملي

ضع قائمة فحص للمنتج قبل عرضه، ودوّن العيوب، واستخدم صورًا حقيقية، وأجب عن الأسئلة بوضوح. وإذا اكتشفت خطأ في السعر أو الوصف بعد النشر، صححه وأبلغ من تأثر به. لا تجعل سرعة البيع تسبق حق العميل في المعرفة.

## خلاصة ومراجع

التجارة الأخلاقية تبني سمعة طويلة الأمد وتقلل الخصومات. المرجع القرآني: المطففين 1–3، والإسراء 35، والنساء 29. هذه مادة تربوية عامة وليست فتوى في عقد بعينه.', '[{"title_ar":"القرآن الكريم — المطففين 1–3","url":"https://quran.com/83/1-3","source_type":"quran","locator_ar":"المطففين 1–3"},{"title_ar":"القرآن الكريم — الإسراء 35","url":"https://quran.com/17/35","source_type":"quran","locator_ar":"الإسراء 35"},{"title_ar":"القرآن الكريم — النساء 29","url":"https://quran.com/4/29","source_type":"quran","locator_ar":"النساء 29"}]'::jsonb),
('zikr-article-deep-05', '# بر الوالدين وصلة الرحم في الحياة اليومية

جعل القرآن الإحسان إلى الوالدين من أعظم أبواب البر، وربط الأمر بتوحيد الله في سورة الإسراء. ولا يقتصر البر على الكلمات اللطيفة؛ بل يظهر في حسن الاستماع، وخفض الجناح، وتقديم العون الممكن، واختيار الوقت والأسلوب المناسبين عند الاختلاف.

## البر العملي

قد يكون البر اتصالًا منتظمًا، أو زيارة، أو قضاء حاجة، أو رعاية عند المرض، أو سؤالًا صادقًا عن الحال. لا يشترط أن تكون الأعمال كبيرة حتى يكون لها أثر. المهم أن تراعي قدرة الوالدين وظروفهما، وألا تتحول المساعدة إلى منّة أو وسيلة للسيطرة.

## عند وجود خلاف

الاختلاف لا يسقط واجب الاحترام، لكنه لا يعني أيضًا أن يوافق الإنسان على كل طلب مهما كان. تُدار المسألة بالرفق والشرح والبحث عن بديل مباح، ويُستعان بأهل الحكمة عند تعقد الخلاف. وفي الأمور التي تتعلق بالضرر أو الحقوق المالية أو القرارات الأسرية، ينبغي طلب نصيحة مختص موثوق وعدم الاكتفاء بمنشور عام.

## صلة الرحم

تتفاوت صلة الرحم بحسب القرب والحاجة والقدرة والعرف. قد تكون بالزيارة أو الاتصال أو المساعدة أو السؤال، وقد تحتاج إلى حدود آمنة إذا وجدت إساءة أو ضرر. لا ينبغي استخدام النصوص لإجبار شخص على تحمل الأذى، كما لا ينبغي اتخاذ خلاف عابر سببًا لقطع العلاقات.

## خطة قابلة للاستمرار

اختر وقتًا ثابتًا للسؤال عن الوالدين، وحدد احتياجًا عمليًا واحدًا يمكنك المساعدة فيه، ثم راجع ما إذا كانت طريقتك مناسبة لهما. وعند زيارة قريب، ابدأ بالسلام والسؤال قبل فتح ملفات الخلاف.

## مصادر القراءة

القرآن الكريم: الإسراء 23–24، والنساء 36، ومحمد 22–23. هذه مادة تربوية عامة وليست حكمًا تفصيليًا على حالة أسرية بعينها.', '[{"title_ar":"القرآن الكريم — الإسراء 23–24","url":"https://quran.com/17/23-24","source_type":"quran","locator_ar":"الإسراء 23–24"},{"title_ar":"القرآن الكريم — النساء 36","url":"https://quran.com/4/36","source_type":"quran","locator_ar":"النساء 36"},{"title_ar":"القرآن الكريم — محمد 22–23","url":"https://quran.com/47/22-23","source_type":"quran","locator_ar":"محمد 22–23"}]'::jsonb),
('zikr-article-expansion-20', '# مواجهة الشائعات والتثبت من الأخبار

تنتشر الشائعة بسرعة عندما يُعاد إرسال الخبر قبل معرفة مصدره. وقد يكون الخبر صورة قديمة، أو اقتباسًا مبتورًا، أو حديثًا لا يثبت، أو معلومة صحيحة أُخرجت من سياقها. لذلك لا يكفي أن يكون المحتوى مؤثرًا أو أن يرسله شخص نثق به؛ المطلوب أن نعرف مصدره ونتأكد من دلالته.

## قاعدة التثبت

توجه سورة الحجرات في الآية 6 إلى التثبت من الأخبار، حتى لا يصيب الناس ضرر بسبب الجهل ثم يقع الندم. ويقرر القرآن كذلك مسؤولية السمع والبصر والفؤاد في سورة الإسراء 36. ويبدأ التطبيق بالسؤال: من نشر الخبر أولًا؟ هل يوجد رابط للمصدر الأصلي؟ هل التاريخ صحيح؟ هل النص كامل أم مقتطع؟

## الأخبار الدينية

قبل نشر حديث، ابحث عن مصدره ودرجته، ولا تكتف بصورة تحمل عبارة «قال رسول الله ﷺ». وقبل نقل حكم شرعي، تحقق هل هو فتوى في واقعة محددة أم حكم عام، وهل ذكر صاحبه شروطه واستثناءاته. الآية أو الحديث لا يُستخدم لتأييد معنى لم يدل عليه النص.

## الأخبار والصور الرقمية

استخدم البحث العكسي عن الصور عند الشك، وافتح الرابط الأصلي، واقرأ ما قبل الاقتباس وما بعده. قارن الخبر بمصدر رسمي أو أكثر من جهة مستقلة، وانتبه إلى الحسابات المنتحلة والعناوين المثيرة. إذا لم تستطع التحقق، فالتوقف عن النشر موقف مسؤول.

## ماذا نفعل بعد نشر خطأ؟

صحح المنشور بوضوح، واذكر ما تغير، واعتذر عند الحاجة. لا تمحُ الأثر وكأن شيئًا لم يحدث إذا كان الناس قد اعتمدوا على المعلومة.

## خلاصة ومراجع

التثبت مسؤولية اجتماعية. المراجع: الحجرات 6، والإسراء 36، والنور 15–16. وتُراجع الأحاديث في مصادرها الأصلية مع بيان درجتها. هذه مادة توعوية عامة وليست بديلًا عن التحقق العلمي.', '[{"title_ar":"القرآن الكريم — الحجرات 6","url":"https://quran.com/49/6","source_type":"quran","locator_ar":"الحجرات 6"},{"title_ar":"القرآن الكريم — النور 15–16","url":"https://quran.com/24/15-16","source_type":"quran","locator_ar":"النور 15–16"},{"title_ar":"القرآن الكريم — الإسراء 36","url":"https://quran.com/17/36","source_type":"quran","locator_ar":"الإسراء 36"}]'::jsonb)
)
UPDATE public.content_library cl
SET body_ar=e.body_ar,
    metadata=coalesce(cl.metadata,'{}'::jsonb)||jsonb_build_object(
      'content_depth_version',1,'references',e.refs,'editorial_status','published'
    )
FROM expanded_articles e
WHERE cl.slug=e.slug AND cl.published=true AND cl.review_status='approved';

